async def act(page):
    # This action will use the site-aware search helper to find the target article,
    # open it, and inspect accessible images for the substring "live" in alt,
    # aria-label, or nearby figcaption text.

    keyword = "Downing Street insists negotiations over US-UK tech deal still live"

    # Use the knowledge-base search helper which drives the visible search widget.
    # This helper will navigate to '/' as its first action.
    try:
        results = await create_curated_collection_by_search(page, keyword, max_results=0, resolve_links=True)
    except Exception:
        results = []

    # Fallback to a shorter query if full-title search yields nothing.
    if not results:
        try:
            results = await create_curated_collection_by_search(page, "Downing Street", max_results=0, resolve_links=True)
        except Exception:
            results = []

    # If still no results, we cannot open the article to check images.
    if not results:
        print("No")
        return

    # Prefer a result whose title contains the full keyword (case-insensitive).
    target = None
    for item in results:
        title = (item.get("title") or "").strip()
        if keyword.lower() in title.lower():
            target = item
            break
    if target is None:
        # Fallback to first search result
        target = results[0]

    url = target.get("url")
    if not url:
        print("No")
        return

    # Navigate to the article page. Use relative or absolute URL as provided.
    await page.goto(url)
    # Give client-side rendering a moment if needed
    try:
        await page.wait_for_load_state("networkidle", timeout=3000)
    except Exception:
        # small sleep to allow DOM updates
        import asyncio
        await asyncio.sleep(0.5)

    # Find all accessible images and inspect alt, aria-label, and nearby figcaption text.
    img_locator = page.get_by_role("img")
    try:
        count = await img_locator.count()
    except Exception:
        count = 0

    found = False
    for i in range(count):
        img = img_locator.nth(i)
        try:
            alt = await img.get_attribute("alt") or ""
        except Exception:
            alt = ""
        try:
            aria = await img.get_attribute("aria-label") or ""
        except Exception:
            aria = ""
        # Extract nearby figcaption if present (closest figure > figcaption or parent's figcaption)
        caption = ""
        try:
            caption = await img.evaluate(
                "el => { const fig = el.closest('figure'); if(fig){ const cap=fig.querySelector('figcaption'); return cap?cap.innerText:'';} const parent = el.parentElement; if(parent){ const cap2 = parent.querySelector('figcaption'); return cap2?cap2.innerText:'';} return ''; }"
            )
            if caption is None:
                caption = ""
        except Exception:
            caption = ""

        combined = " ".join([alt, aria, caption]).lower()
        if "live" in combined:
            found = True
            break

    print("Yes" if found else "No")

